                a_count -= 1
            elif event_type == 'b_start':
                b_count += 1
            elif event_type == 'b_end':
                b_count -= 1
            i += 1

        # After processing all events at current_pos, check state for next region
        if i < len(all_events):
            next_pos = all_events[i][0]

            # We're in the region [current_pos, next_pos)
            if a_count > 0 and b_count == 0:
                # Start or continue a result interval
